# Check for extraction/format failures: numeric compare of extracted vs gold
import json, re, math
rows=[json.loads(l) for l in open('/practice/original/select.jsonl')]
def num(s):
    if s is None: return None
    s=str(s).replace(',','').replace('$','').strip()
    try: return float(s)
    except: return None
mism=0; ex_ok=0
wrong_fin=[r for r in rows if r['finish']=='stop' and not r['correct']]
print('finished wrong', len(wrong_fin))
for r in wrong_fin:
    e=num(r['extracted']); g=num(r['gold'])
    if e is not None and g is not None and abs(e-g)<1e-6:
        mism+=1
        if mism<=5: print('numeric match but marked wrong:', r['qid'], repr(r['extracted']), repr(r['gold']))
print('numeric-equal-but-wrong:', mism)
# gold that are fractions vs extracted decimals
mism2=0
for r in wrong_fin:
    e=num(r['extracted'])
    for m in re.finditer(r'(-?\d+)\s*/\s*(\d+)', str(r['gold'])):
        try: g=int(m.group(1))/int(m.group(2))
        except: continue
        if e is not None and abs(e-g)<1e-6: mism2+=1
print('decimal-equal-to-fraction gold:', mism2)

